348	export async function removeAlias(id: number, mailboxAddress?: string): Promise<Result> {
349	  const { user, address } = await resolveMailbox(mailboxAddress);
350	  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
351	  if (limited) return limited;
352	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
353	  if (!Number.isFinite(id)) return { ok: false, error: "Invalid alias." };
354	
355	  const domain = domainOf(address);
356	  const owned = await ownedDomains(user.id);
