148	/**
149	 * List a page of messages (newest first). `search` runs an IMAP SEARCH across
150	 * subject / from / to / body. Envelopes + a light body snippet only — never the
151	 * full body — so lists stay cheap.
152	 */
153	export async function listMessages(
154	  folder: string,
155	  page: number,
156	  search?: string,
157	  mailboxAddress?: string,
158	): Promise<ListResult> {
159	  const { cred } = await resolveMailbox(mailboxAddress);
160	  const pageNum = Math.max(1, Math.floor(page) || 1);
161	
162	  return withMailbox(
163	    cred,
164	    folder,
165	    async (client) => {
166	      const term = search?.trim();
167	      const query = term
168	        ? { or: [{ subject: term }, { from: term }, { to: term }, { body: term }] }
169	        : { all: true };
170	      const found = await client.search(query, { uid: true });
171	      const uids = (Array.isArray(found) ? found : []).slice().sort((a, b) => b - a); // newest first
172	
173	      const total = uids.length;
174	      const start = (pageNum - 1) * PAGE_SIZE;
175	      const pageUids = uids.slice(start, start + PAGE_SIZE);
176	      if (pageUids.length === 0) {
177	        return { messages: [], total, page: pageNum, pageSize: PAGE_SIZE };
178	      }
179	
180	      // 1) Cheap metadata pass for the page.
181	      const metaByUid = new Map<number, MessageSummary>();
182	      const previewPartByUid = new Map<number, string>();
183	      for await (const msg of client.fetch(
184	        pageUids,
185	        { uid: true, envelope: true, flags: true, internalDate: true, bodyStructure: true },
186	        { uid: true },
187	      )) {
188	        const flags = readFlags(msg.flags);
189	        const env = msg.envelope;
190	        metaByUid.set(msg.uid, {
191	          uid: msg.uid,
192	          folder,
193	          from: toMailAddress(env?.from?.[0]),
194	          to: toMailAddresses(env?.to),
195	          subject: env?.subject || "(no subject)",
196	          preview: "",
197	          date: isoDate(msg),
198	          seen: flags.seen,
199	          flagged: flags.flagged,
200	          answered: flags.answered,
201	          hasAttachments: structureHasAttachments(msg.bodyStructure),
202	        });
203	        previewPartByUid.set(msg.uid, findPreviewPart(msg.bodyStructure).part);
204	      }
205	
206	      // 2) Snippet pass (partial, PEEKed downloads — no flag changes).
207	      await Promise.all(
208	        pageUids.map(async (uid) => {
209	          const summary = metaByUid.get(uid);
210	          if (!summary) return;
211	          summary.preview = await fetchPreview(client, uid, previewPartByUid.get(uid) || "1");
212	        }),
213	      );
214	
215	      const messages = pageUids
216	        .map((uid) => metaByUid.get(uid))
217	        .filter((m): m is MessageSummary => Boolean(m));
218	      return { messages, total, page: pageNum, pageSize: PAGE_SIZE };
219	    },
220	    { readOnly: true },
221	  );
222	}
