505	/** Delete a message: move to Trash, or permanently expunge if already in Trash. */
506	export async function deleteMessage(folder: string, uid: number, mailboxAddress?: string): Promise<void> {
507	  const { user, cred } = await resolveMailbox(mailboxAddress);
508	  enforceRateLimit(`mail:delete:${user.id}`, { max: 120, windowMs: 60 * 1000 });
509	
510	  await withImap(cred, async (client) => {
511	    // Determine the Trash folder path.
512	    let trashPath = "Trash";
513	    try {
514	      const list = await client.list();
515	      const trash = list.find((f) => folderRole(f.path, f.specialUse) === "trash");
516	      if (trash) trashPath = trash.path;
517	    } catch {
518	      /* fall back to "Trash" */
519	    }
520	
521	    const inTrash = folderRole(folder) === "trash" || folder === trashPath;
522	    const lock = await client.getMailboxLock(folder);
523	    try {
524	      if (inTrash) {
525	        await client.messageDelete(String(uid), { uid: true });
526	      } else {
527	        await client.messageMove(String(uid), trashPath, { uid: true });
528	      }
529	    } finally {
530	      lock.release();
531	    }
532	  });
533	}
