418	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
419	  const user = await requireUser();
420	
421	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
422	  if (!sub) return { error: "Subscription not found." };
423	  if (sub.userId !== user.id) return { error: "Not your subscription." };
424	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
425	  if (sub.verified) return { ok: true };
426	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
427	
428	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
429	    max: 6,
430	    windowMs: 60_000,
431	  });
432	  if (!rl.ok) {
433	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
434	  }
435	
436	  const domain = sub.domainName;
437	  const expected = `nxeon-verify=${sub.verifyToken}`;
438	
439	  // Primary signal: the verification TXT record must contain our exact token.
440	  let tokenFound = false;
441	  try {
442	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
443	    // Each record may be split into multiple strings — join per-record chunks.
444	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
445	  } catch {
446	    tokenFound = false;
447	  }
448	
449	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
450	  let mxOk = false;
451	  try {
452	    const mx = await resolveMx(domain);
453	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
454	  } catch {
455	    mxOk = false;
456	  }
457	
458	  if (!tokenFound) {
459	    return {
460	      error: mxOk
461	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
462	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
463	    };
464	  }
465	
466	  await db.emailSubscription.update({
467	    where: { id: sub.id },
468	    data: { verified: true, verifiedAt: new Date() },
469	  });
470	
471	  await db.auditLog.create({
472	    data: {
473	      userId: user.id,
474	      action: "emailhosting.verify",
475	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
476	    },
477	  });
478	  revalidatePath("/dashboard/email");
479	  return { ok: true };
480	}
